// Example with a valid date after 1970
gsql_ts_to_epoch_seconds_signed("2022-06-30 22:08:28") -> 1656652105

// Example with a date before 1970 (returns a negative epoch value)
gsql_ts_to_epoch_seconds_signed("1969-12-31 23:59:59") -> -1

